[CmdletBinding()] param([Parameter(Mandatory=$true)][string]$TaskId,[Parameter(Mandatory=$true)][string]$Title,[ValidateSet('T0','T1','T2','T3','T4')][string]$RequestedTier='T1',[Parameter(Mandatory=$true)][string[]]$ChangeDomains,[string[]]$ProtectedChanges=@(),[ValidateSet('none','reversible','backward_compatible','destructive','irreversible')][string]$MigrationClass='none',[string]$BaseRef,[string]$RootPath='.')
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'Pipeline.Common.psm1') -Force;$a=@('new','--task',$TaskId,'--title',$Title,'--tier',$RequestedTier,'--domains',($ChangeDomains -join ','),'--migration',$MigrationClass);if($ProtectedChanges.Count){$a+=@('--protected',($ProtectedChanges -join ','))};if($BaseRef){$a+=@('--base-ref',$BaseRef)};Invoke-WebPipeline $RootPath $a
